     "nar": "La direttiva quadro ottantanove barra trecentonovantuno del Consiglio, del dodici giugno millenovecentoottantanove, è il fondamento del sistema europeo di salute e sicurezza sul lavoro. L’articolo sei elenca i principi generali di prevenzione che il datore di lavoro deve applicare. Il primo è evitare i rischi; quelli che non possono essere evitati vanno valutati. Occorre poi combattere i rischi alla fonte e adeguare il lavoro all’uomo, in particolare per quanto riguarda la concezione dei posti di lavoro, la scelta delle attrezzature e dei metodi di lavoro, per attenuare il lavoro monotono e ripetitivo. Si deve tenere conto del grado di evoluzione della tecnica, sostituire ciò che è pericoloso con ciò che non lo è o lo è meno, programmare la prevenzione in modo coerente, integrando tecnica, organizzazione del lavoro, condizioni di lavoro, relazioni sociali e influenza dei fattori ambientali. La protezione collettiva ha la priorità su quella individuale, e ai lavoratori vanno impartite istruzioni adeguate. La direttiva ha introdotto anche l’obbligo generale di valutare i rischi, la designazione di lavoratori incaricati della prevenzione, l’informazione, la consultazione e la partecipazione equilibrata dei lavoratori. Il decreto legislativo ottantuno del duemilaotto riprende questi principi nelle misure generali di tutela dell’articolo quindici; le direttive particolari disciplinano i singoli rischi.",
