     "nar": "Le fonti della prevenzione sono ordinate gerarchicamente. Al vertice la Costituzione; poi il diritto dell'Unione europea, con la direttiva quadro e regolamenti direttamente applicabili come REACH, CLP, il nuovo regolamento macchine e il regolamento DPI; quindi il codice civile, con la norma di chiusura dell'articolo duemilaottantasette, e il Testo unico, che si applica a tutti i settori e a tutte le tipologie di lavoratori. Completano il quadro i decreti attuativi, gli Accordi Stato-Regioni, le norme tecniche e le buone prassi.",
