     "nar": "Le responsabilità sono di natura penale e civile. In sede penale rispondono i titolari delle posizioni di garanzia per le contravvenzioni previste dal decreto e, in caso di infortunio, per omicidio o lesioni colposi. Particolare rilievo assume la causalità omissiva: non impedire un evento che si ha l'obbligo giuridico di impedire equivale a cagionarlo. L'RSPP è un consulente privo di poteri decisionali, ma la giurisprudenza ne riconosce la responsabilità in concorso quando un errore di valutazione o un'omessa segnalazione hanno contribuito all'evento. In sede civile il datore di lavoro risponde ai sensi dell'articolo duemilaottantasette, accanto alla tutela assicurativa INAIL.",
