     "nar": "Quando un infortunio grave o mortale deriva dalla violazione delle norme di sicurezza, risponde anche la società, se il reato le ha procurato un interesse o un vantaggio, ad esempio un risparmio sui costi della sicurezza. Per l’omicidio colposo nelle aziende a rischio particolare la sanzione arriva a mille quote, oltre alle sanzioni interdittive. La società si difende dimostrando di aver adottato ed efficacemente attuato, prima del fatto, un modello organizzativo idoneo.",
