     "rif": "D.lgs. 81/2008, artt. 5-10",
     "nar": "Il testo unico organizza la prevenzione su più livelli istituzionali. A livello nazionale, il Comitato per l’indirizzo e la valutazione delle politiche attive, previsto dall’articolo cinque, stabilisce le linee comuni delle politiche nazionali e individua obiettivi e programmi. La Commissione consultiva permanente dell’articolo sei esamina i problemi applicativi della normativa, valida le buone prassi, elabora le procedure standardizzate per la valutazione dei rischi e i criteri per le attività di vigilanza. A livello territoriale, i Comitati regionali di coordinamento dell’articolo sette programmano e coordinano le attività di prevenzione e vigilanza svolte da aziende sanitarie, Ispettorato, Vigili del fuoco e INAIL. L’articolo otto istituisce il Sistema informativo nazionale per la prevenzione, che raccoglie e integra i dati su infortuni, malattie professionali, esposizioni e attività di vigilanza, per orientare le politiche. L’articolo nove attribuisce all’INAIL e agli altri enti pubblici compiti di informazione, formazione, assistenza, consulenza e ricerca. L’INAIL sostiene la prevenzione anche con strumenti economici: i bandi per il finanziamento di progetti di miglioramento della sicurezza e la riduzione del tasso medio di premio per le aziende che hanno effettuato interventi migliorativi.",
