     "appro": "La sentenza ThyssenKrupp ha chiarito che nelle organizzazioni complesse le posizioni di garanzia si distribuiscono secondo le competenze e i poteri: datore di lavoro, dirigenti e preposti rispondono ciascuno dei rischi che sono chiamati a gestire. Ne deriva l’importanza di un organigramma della sicurezza coerente con le deleghe, le procure e i budget effettivamente assegnati.",
     "rif": "Art. 2, c. 1, lett. b) e t); art. 299 D.lgs. 81/2008 · Cass. pen., S.U., n. 38343/2014",
     "nar": "Chi è il datore di lavoro in una società? È chi ha la responsabilità dell’organizzazione ed esercita i poteri decisionali e di spesa. In assenza di deleghe la posizione di garanzia grava sull’intero consiglio di amministrazione; con deleghe, sull’amministratore delegato. Nelle pubbliche amministrazioni è il dirigente individuato dall’organo di vertice. Le Sezioni Unite della Cassazione, nel caso ThyssenKrupp, hanno descritto il garante come gestore del rischio: risponde chi ha il potere di governare l’area in cui l’evento si è verificato.",
