     "nar": "Il medico competente è il medico in possesso dei titoli previsti dall’articolo trentotto, tra cui la specializzazione in medicina del lavoro o in medicina preventiva dei lavoratori, oppure la docenza o la specializzazione in discipline affini con il percorso formativo previsto, e iscritto nell’elenco nazionale tenuto dal Ministero della salute. È nominato dal datore di lavoro quando la valutazione dei rischi evidenzia l’obbligo di sorveglianza sanitaria. L’articolo venticinque ne elenca gli obblighi: collabora con il datore di lavoro e con il servizio di prevenzione alla valutazione dei rischi e alla predisposizione delle misure, anche ai fini della programmazione della sorveglianza sanitaria, della formazione e dell’organizzazione del primo soccorso; programma ed effettua la sorveglianza sanitaria secondo protocolli definiti; istituisce, aggiorna e custodisce le cartelle sanitarie e di rischio; informa i lavoratori sul significato degli accertamenti; comunica per iscritto, in occasione della riunione periodica, i risultati anonimi collettivi; visita gli ambienti di lavoro almeno una volta all’anno, o con cadenza diversa stabilita in base alla valutazione dei rischi. Entro il trentuno marzo di ogni anno trasmette all’INAIL, in via telematica, le informazioni aggregate sanitarie e di rischio dei lavoratori sottoposti a sorveglianza, previste dall’Allegato tre B.",
