     "nar": "Il giudizio di idoneità espresso dal medico competente non è un atto burocratico: vincola l’organizzazione del lavoro. L’articolo diciotto, alla lettera bb, impone al datore di lavoro e ai dirigenti di vigilare affinché i lavoratori per i quali vige l’obbligo di sorveglianza sanitaria non siano adibiti alla mansione lavorativa specifica senza il prescritto giudizio di idoneità. Quando il giudizio contiene limitazioni o prescrizioni, ad esempio il divieto di sollevare carichi oltre un certo peso o l’obbligo di usare otoprotettori, queste devono essere comunicate ai preposti che organizzano concretamente il lavoro, e la loro attuazione va verificata. L’articolo quarantadue disciplina l’inidoneità: il datore di lavoro attua le misure indicate dal medico e, qualora le stesse prevedano un’inidoneità alla mansione specifica, adibisce il lavoratore, ove possibile, a mansioni equivalenti o, in difetto, a mansioni inferiori, garantendo il trattamento corrispondente alle mansioni di provenienza. Contro il giudizio del medico competente il lavoratore e il datore di lavoro possono ricorrere, entro trenta giorni, all’organo di vigilanza territorialmente competente. Un giudizio con limitazioni non attuato in reparto è una delle carenze più frequenti rilevate dopo un infortunio o una malattia professionale.",
