     "nar": "La riunione periodica dell’articolo trentacinque è il principale momento di confronto tra i soggetti della prevenzione. Nelle aziende e unità produttive con più di quindici lavoratori il datore di lavoro, direttamente o tramite il servizio di prevenzione e protezione, la indice almeno una volta all’anno. Vi partecipano il datore di lavoro o un suo rappresentante, il responsabile del servizio di prevenzione e protezione, il medico competente, ove nominato, e il rappresentante dei lavoratori per la sicurezza. Nel corso della riunione si esaminano il documento di valutazione dei rischi, l’andamento degli infortuni, delle malattie professionali e della sorveglianza sanitaria, i criteri di scelta, le caratteristiche tecniche e l’efficacia dei dispositivi di protezione individuale, i programmi di informazione e formazione di dirigenti, preposti e lavoratori. Si possono individuare codici di comportamento, buone prassi e obiettivi di miglioramento della sicurezza. La riunione va convocata anche quando si verificano variazioni significative delle condizioni di esposizione al rischio, ad esempio con nuove tecnologie. Della riunione si redige un verbale, tenuto a disposizione dei partecipanti per la consultazione. Nelle aziende fino a quindici lavoratori il rappresentante dei lavoratori può chiederne la convocazione in presenza di variazioni significative.",
