     "appro": "Il lavoratore non interviene sull’impianto: segnala prese danneggiate, cavi con isolamento lesionato, interruttori che scattano ripetutamente.",
     "rif": "D.P.R. 22 ottobre 2001, n. 462 · D.M. 22 gennaio 2008, n. 37 · D.lgs. 81/2008, art. 80",
     "nar": "Negli ambienti a rischio basso il pericolo elettrico più frequente è il contatto indiretto, cioè il contatto con una parte metallica che è andata in tensione per un guasto. La protezione si basa sull’impianto di terra coordinato con gli interruttori differenziali, che interrompono l’alimentazione in una frazione di secondo. L’impianto deve essere realizzato da un’impresa abilitata, che rilascia la dichiarazione di conformità prevista dal decreto ministeriale trentasette del duemilaotto. Il decreto del Presidente della Repubblica quattrocentosessantadue del duemilauno impone poi verifiche periodiche dell’impianto di terra: ogni cinque anni nella generalità dei luoghi di lavoro, ogni due anni nei cantieri, nei locali adibiti a uso medico e negli ambienti a maggior rischio in caso di incendio. La verifica è richiesta dal datore di lavoro e svolta dall’INAIL, dalle aziende sanitarie o agenzie regionali, oppure da un organismo abilitato. Anche l’interruttore differenziale va provato periodicamente con il tasto di prova, secondo le istruzioni del costruttore. Il lavoratore non interviene sull’impianto, ma ha un ruolo importante: segnalare subito prese danneggiate, cavi con l’isolamento lesionato, interruttori che scattano ripetutamente o apparecchi che danno la scossa.",
