     "rif": "ISO 45001:2018/Amd 1:2024 · ISO 50001:2018/Amd 1:2024 · ISO 14001:2015/Amd 1:2024",
     "nar": "Nel febbraio duemilaventiquattro l’organizzazione internazionale di normazione ha pubblicato un emendamento comune a tutte le norme sui sistemi di gestione costruite sulla struttura armonizzata, tra cui la ISO quarantacinquemilauno per la salute e sicurezza, la ISO cinquantamilauno per l’energia e la ISO quattordicimilauno per l’ambiente. L’emendamento aggiunge due frasi. Al punto quattro uno, sul contesto dell’organizzazione, richiede di determinare se il cambiamento climatico è un fattore rilevante. Al punto quattro due precisa che le parti interessate pertinenti possono avere requisiti legati al cambiamento climatico. Per un sistema di gestione della sicurezza le implicazioni sono concrete: l’aumento delle ondate di calore incide sullo stress termico dei lavoratori all’aperto e negli ambienti caldi; gli eventi meteorologici estremi incidono sulla gestione delle emergenze, sulla stabilità delle strutture e sulla continuità operativa; la diffusione di vettori come zanzare e zecche può modificare il rischio biologico. Il requisito non impone di considerare sempre rilevante il clima, ma di motivare la conclusione. In audit si verifica la coerenza tra l’analisi del contesto, la valutazione dei rischi, i piani di emergenza e le misure effettivamente adottate, ad esempio un piano di gestione del caldo.",
     "est": true,
     "ancora": "Il processo di gestione del rischio (UNI ISO 31000)"
