      "Misure: lavori in orario di fermo reparto, bonifica e permesso di lavoro a caldo, delimitazione delle aree, coordinamento con i preposti, riunione di coordinamento iniziale verbalizzata",
      "Costi della sicurezza da interferenze indicati nel contratto e non soggetti a ribasso (art. 26, c. 5)",
