     "nar": "I dispositivi di protezione individuale si adottano quando i rischi non possono essere evitati o ridotti a sufficienza con misure tecniche o organizzative. L’articolo settantasette del testo unico pone a carico del datore di lavoro la scelta dei dispositivi, sulla base della valutazione dei rischi e delle caratteristiche dei prodotti disponibili sul mercato, la fornitura gratuita, la manutenzione e la sostituzione. I dispositivi sono di norma destinati all’uso personale e la consegna viene registrata, con la firma del lavoratore. Il datore di lavoro fornisce istruzioni comprensibili e assicura una formazione adeguata; per i dispositivi di terza categoria, che proteggono da rischi gravi o mortali, e per i protettori dell’udito l’addestramento è sempre obbligatorio. L’articolo settantotto definisce gli obblighi del lavoratore: utilizzare i dispositivi conformemente all’informazione, alla formazione e all’addestramento ricevuti, averne cura, non apportarvi modifiche di propria iniziativa, segnalare immediatamente qualsiasi difetto o inconveniente al datore di lavoro, al dirigente o al preposto e seguire le procedure di riconsegna. I dispositivi hanno una durata limitata: guanti, filtri, calzature e otoprotettori vanno sostituiti secondo le istruzioni del fabbricante o quando risultano danneggiati.",
