     "nar": "La segnaletica di sicurezza comunica un messaggio mediante forme e colori normalizzati, comprensibili anche senza ricorrere alla lettura. I pittogrammi riprodotti sono quelli ufficiali della norma UNI EN ISO 7010. I segnali di avvertimento sono triangolari, gialli con bordo nero, e indicano un pericolo. I segnali di divieto sono rotondi, con bordo e barra rossi. I segnali di prescrizione sono rotondi e azzurri e impongono un comportamento, quale l'uso di un dispositivo di protezione. I segnali di salvataggio sono verdi e indicano uscite, percorsi di esodo e presidi di primo soccorso. I segnali antincendio sono rossi e quadrati e indicano estintori, idranti e pulsanti di allarme. Le schede di ciascuna famiglia riportano i relativi pittogrammi."
