     "rif": "D.P.R. 1° agosto 2011, n. 151, artt. 3-5 e Allegato I · D.M. 7 agosto 2012",
     "nar": "Il regolamento di prevenzione incendi, decreto del Presidente della Repubblica centocinquantuno del duemilaundici, individua nell’Allegato uno ottanta attività soggette ai controlli dei Vigili del fuoco, come depositi di liquidi infiammabili, officine con più di un certo numero di addetti, impianti di produzione di calore oltre centosedici chilowatt, autorimesse e attività commerciali di grandi dimensioni. Ogni attività è classificata, in base alla dimensione e alla complessità, in tre categorie con procedimenti diversi. Per le attività di categoria A, a rischio più basso, si presenta la segnalazione certificata di inizio attività prima dell’avvio, e i controlli avvengono a campione. Per la categoria B si presenta preventivamente il progetto per la valutazione, poi la segnalazione, con controlli anche a campione. Per la categoria C, la più complessa, oltre alla valutazione del progetto, dopo la segnalazione i Vigili del fuoco eseguono un sopralluogo entro sessanta giorni e rilasciano il certificato di prevenzione incendi. Il titolare deve inoltre presentare periodicamente l’attestazione di rinnovo della conformità antincendio, di norma ogni cinque anni. Ogni modifica che comporti un aggravio delle condizioni di sicurezza richiede un nuovo procedimento: va valutata prima di intervenire su lavorazioni, depositi o disposizione dei locali.",
