     "rif": "D.lgs. 81/2008, artt. 18 c. 1 lett. o), 26 c. 5 e 50",
     "nar": "Il rappresentante dei lavoratori per la sicurezza può svolgere il proprio ruolo solo se dispone delle informazioni necessarie. L’articolo cinquanta prevede che riceva le informazioni e la documentazione aziendale inerente alla valutazione dei rischi e alle misure di prevenzione, nonché quelle relative alle sostanze e alle miscele pericolose, alle macchine, agli impianti, all’organizzazione e agli ambienti di lavoro, agli infortuni e alle malattie professionali. Su sua richiesta e per l’espletamento della funzione riceve copia del documento di valutazione dei rischi; l’articolo diciotto pone a carico del datore di lavoro l’obbligo di consegnarla tempestivamente. Il rappresentante territoriale, esterno all’azienda, esercita invece il diritto consultando il documento esclusivamente in azienda. Per gli appalti, l’articolo ventisei prevede che il documento unico di valutazione dei rischi da interferenze sia messo a disposizione dei rappresentanti dei lavoratori. Il rappresentante è tenuto al rispetto delle disposizioni sulla protezione dei dati personali e del segreto industriale relativamente alle informazioni contenute nel documento e alle altre informazioni aziendali, e a usarle solo per l’esercizio della funzione. Una consegna tempestiva e completa dei documenti è anche un investimento nella qualità delle relazioni.",
