     "nar": "Nel linguaggio del testo unico formazione, informazione e addestramento sono attività distinte. L’articolo due, alla lettera cc, definisce l’addestramento come il complesso delle attività dirette a fare apprendere ai lavoratori l’uso corretto di attrezzature, macchine, impianti, sostanze, dispositivi, anche di protezione individuale, e le procedure di lavoro. L’articolo trentasette, comma cinque, stabilisce che l’addestramento viene effettuato da persona esperta e sul luogo di lavoro, e dalla riforma del duemilaventuno precisa che l’addestramento consiste nella prova pratica per l’uso corretto e in sicurezza di attrezzature, macchine, impianti, sostanze e dispositivi, e nell’esercitazione applicata per le procedure di lavoro in sicurezza; gli interventi di addestramento effettuati devono essere tracciati in apposito registro, anche informatizzato. L’addestramento è sempre obbligatorio per i dispositivi di protezione individuale di terza categoria e per i protettori dell’udito, e per le attrezzature che richiedono conoscenze o responsabilità particolari, secondo l’articolo settantatré. Va ripetuto quando si introducono nuove attrezzature, tecnologie o procedure. Il registro indica data, contenuti, addestratore, durata ed esito della verifica pratica: è la prova documentale che l’abilità è stata effettivamente trasferita, distinta dall’attestato del corso teorico.",
