      "Livello 3 – Comportamento: trasferimento nel lavoro (osservazioni del preposto, audit di comportamento a 30–90 giorni)",
      "Livello 4 – Risultati: effetti sull’organizzazione (quasi incidenti segnalati, infortuni, non conformità, uso corretto dei DPI)",
