     "appro": "Esempio: dopo un corso sull’uso dei carrelli elevatori, il preposto osserva per tre settimane cinque comportamenti chiave (cintura, velocità, forche abbassate in marcia, precedenza ai pedoni, verifica pre-uso), registra la percentuale di comportamenti sicuri e la confronta con quella rilevata prima del corso. Il dato documenta la verifica di efficacia e orienta eventuali interventi di addestramento mirato.",
     "rif": "Art. 37 D.lgs. 81/2008 · Accordo Stato-Regioni 17/04/2025, Parte I",
     "nar": "L’Accordo del 2025 richiede la verifica dell’efficacia della formazione durante l’attività lavorativa. A tal fine è utile il modello a quattro livelli: la reazione, ossia il gradimento; l’apprendimento, misurato mediante il test; il comportamento, osservato sul luogo di lavoro nelle settimane successive; i risultati, quali la riduzione dei quasi incidenti. A titolo di esempio, dopo un corso per carrellisti il preposto osserva per tre settimane alcuni comportamenti chiave e registra la percentuale di comportamenti sicuri.",
