     "nar": "La formazione è uno degli obblighi più verificati e la prova del suo adempimento è documentale. Il punto di partenza è il progetto formativo, che indica obiettivi, contenuti, durata, metodologia didattica, docenti e modalità di verifica. Per la formazione in aula o in videoconferenza sincrona si conserva il registro presenze, con firme e orari di ingresso e uscita; per l’e-learning la piattaforma traccia i tempi di fruizione, gli accessi e gli esiti dei test. Al termine si svolge la verifica di apprendimento e, per l’addestramento, una prova pratica documentata. L’attestato riporta gli elementi minimi previsti dall’Accordo Stato Regioni del diciassette aprile duemilaventicinque, tra cui i dati del soggetto formatore, del partecipante, del corso, della durata e del superamento della verifica. Per ogni lavoratore conviene tenere un fascicolo formativo e uno scadenzario degli aggiornamenti: quinquennale per lavoratori e dirigenti, biennale per i preposti, annuale per i rappresentanti dei lavoratori. Lo scadenzario va collegato all’organigramma: un cambio di mansione, l’introduzione di nuove attrezzature o la nomina a preposto generano nuovi obblighi formativi che il sistema deve intercettare per tempo.",
